W={
'nghe-daoduc-42':["Chi phí giao tiếp trực tuyến thường thấp, không cao hơn mọi hình thức khác.","Giao tiếp mạng giúp kết nối người cùng sở thích, đó là ưu điểm.","Nhược điểm: thiếu tín hiệu phi ngôn ngữ như nét mặt; nguy cơ lộ bảo mật và riêng tư.","Giao tiếp mạng không cần ở cùng một nơi, đó là ưu điểm."],
'nghe-daoduc-43':["Chia sẻ tin giật gân khi chưa kiểm chứng làm lan tin sai.","Mỉa mai người khác để câu lượt xem là thiếu tôn trọng.","Đăng ảnh bạn khi chưa hỏi ý kiến xâm phạm quyền riêng tư.","Phản hồi tôn trọng và kiểm chứng trước khi chia sẻ thể hiện tính nhân văn."],
'nghe-daoduc-44':["Chửi lại ẩn danh làm tăng bạo lực mạng.","Chia sẻ bài công kích khiến bạn bị tổn thương nhiều hơn.","Không công kích, động viên bạn và báo người có trách nhiệm là ứng xử nhân văn.","Nhấn thích bài công kích là tiếp tay cho hành vi tiêu cực."],
'nghe-daoduc-45':["Hiểu sai xảy ra cả khi nhắn tin lẫn nhiều hình thức khác.","Văn bản thiếu giọng điệu và nét mặt nên dễ bị hiểu sai; cần diễn đạt rõ ràng.","Không chỉ xảy ra với tiếng nước ngoài.","Vẫn có thể xảy ra dù đã viết bằng chữ."],
'nghe-nghe-46':["Thiết kế kiến trúc phần mềm thuộc nhóm phát triển phần mềm.","Thiết kế CSDL thuộc nhóm CSDL.","Chẩn đoán lỗi, vệ sinh, thay linh kiện, cài hệ điều hành và phần mềm là sửa chữa, bảo trì.","Biên tập phim hoạt hình thuộc nhóm đa phương tiện."],
'nghe-nghe-47':["Sửa màn hình từng laptop thuộc sửa chữa phần cứng.","Viết phần mềm kế toán thuộc phát triển phần mềm.","Quản trị mạng: cài đặt, cấu hình, giám sát, bảo đảm an toàn và hỗ trợ người dùng.","Tạo nội dung quảng cáo thuộc truyền thông."],
'nghe-nghe-48':["Mạng ngày càng phức tạp chứ không đơn giản.","Máy tính được dùng ngày càng nhiều.","Dịch vụ trực tuyến tăng, không giảm.","Số thiết bị kết nối (IoT) tăng và tấn công mạng tinh vi hơn nên nhu cầu quản trị mạng tăng."],
'nghe-nghe-49':["Thiết kế bố cục trang web thuộc nhóm thiết kế web.","Cấp IP thuộc quản trị mạng.","Quản trị CSDL: cài hệ quản trị, phân quyền, sao lưu – phục hồi, giám sát hiệu năng.","Lắp ráp máy thuộc sửa chữa phần cứng."],
'nghe-nghe-50':["Cài lại hệ điều hành là việc của người sửa chữa, bảo trì.","Tư vấn nâng cấp linh kiện thuộc công việc này.","Khắc phục sự cố phần cứng thuộc công việc này.","Thiết kế và lập trình phần mềm thuộc nhóm nghề phát triển phần mềm, không phải sửa chữa."],
'nghe-nghe-1':["Quản trị mạng lo cài đặt, cấu hình, giám sát hệ thống mạng.","Thiết kế đồ hoạ làm hình ảnh.","Lập trình ứng dụng di động viết ứng dụng.","Kiểm thử tìm lỗi phần mềm."],
'nghe-nghe-2':["Phát triển trò chơi không làm việc phân quyền, sao lưu CSDL.","Thiết kế giao diện web không làm việc này.","Phân quyền, sao lưu – phục hồi dữ liệu là quản trị cơ sở dữ liệu.","Lắp ráp, sửa chữa máy tính không liên quan."],
'nghe-nghe-3':["Viết mã, kiểm thử liên tục ứng dụng điện thoại là lập trình viên di động.","Phân tích dữ liệu không làm ra ứng dụng.","Sửa chữa máy tính làm phần cứng.","Quản trị mạng không viết ứng dụng."],
'nghe-nghe-4':["Phân tích dữ liệu: thu thập, làm sạch, phân tích để hỗ trợ quyết định.","Cài hệ điều hành cho máy lẻ là việc kĩ thuật viên.","Lắp cáp, cấu hình router là quản trị mạng.","Thiết kế bảng mạch là kĩ sư điện tử."],
'nghe-nghe-5':["Soạn văn bản hành chính không phải an toàn thông tin.","An toàn thông tin: phát hiện rủi ro, bảo vệ hệ thống và dữ liệu khỏi tấn công.","Nhập liệu thủ công không phải nhiệm vụ chính.","Thiết kế logo là thiết kế đồ hoạ."],
'nghe-nghe-6':["Sửa chữa, bảo trì: chẩn đoán lỗi, thay linh kiện, cài đặt lại phần mềm.","Thiết kế CSDL ngân hàng là việc của chuyên viên CSDL.","Dựng phim là thiết kế đa phương tiện.","Huấn luyện mô hình học máy là kĩ sư AI."],
'nghe-nghe-7':["Làm việc một mình, hạn chế trao đổi không giúp theo nghề lâu dài.","CNTT thay đổi nhanh nên phải học tập, cập nhật công nghệ mới.","Chỉ thuộc một ngôn ngữ là chưa đủ.","Tránh công cụ mới làm tụt hậu."],
'nghe-nghe-8':["Quản trị mạng không viết đặc tả yêu cầu.","Thiết kế đồ hoạ minh hoạ không làm việc này.","Phân tích nghiệp vụ là cầu nối giữa khách hàng và nhóm kĩ thuật, đặc tả yêu cầu.","Sửa chữa phần cứng không liên quan."],
'nghe-nghe-9':["Quản lí kho dữ liệu giấy không huấn luyện mô hình.","Lắp mạng LAN là kĩ thuật mạng.","Thiết kế web tĩnh không huấn luyện mô hình AI.","Kĩ sư AI/học máy chuẩn bị dữ liệu, xây dựng, huấn luyện và đánh giá mô hình."],
'nghe-nghe-10':["Tốc độ gõ phím không phải mối quan tâm hàng đầu của thiết kế UI/UX.","Số dòng mã là việc của lập trình.","Số máy chủ thuộc hạ tầng.","UI/UX hướng đến người dùng: giao diện thân thiện, dễ hiểu, dễ dùng."],
'nghe-nghe-11':["Thiết kế bao bì không dùng SQL.","Bảo trì thiết bị ngoại vi không dùng SQL.","Lắp ráp phần cứng không dùng SQL.","Phân tích dữ liệu cần SQL và trực quan hoá dữ liệu bằng biểu đồ."],
'nghe-nghe-12':["Tên trường nổi tiếng không phải yếu tố duy nhất.","Lời khuyên của một người không đủ.","Cần cân nhắc cùng sở thích: năng lực bản thân và nhu cầu thị trường lao động.","Chỉ xét mức lương là phiến diện."],
'nghe-nghe-13':["Sản phẩm chưa có người mua vẫn vi phạm giấy phép.","Đổi tên biến không làm hợp lệ.","Mã nguồn vẫn được bảo hộ; sao chép trái giấy phép vi phạm bản quyền và đạo đức nghề nghiệp.","Công khai trên mạng không có nghĩa là được dùng tự do."],
'nghe-nghe-14':["Chia sẻ điểm cho quảng cáo là vi phạm riêng tư.","Cấp toàn quyền cho mọi giáo viên vi phạm quyền tối thiểu.","Quản trị CSDL bảo vệ thông tin cá nhân, chỉ cấp quyền đúng nhu cầu.","Vẫn phải sao lưu."],
'nghe-nghe-15':["Chứng chỉ không thay thế việc học về sau.","Chứng chỉ có giá trị ở cả trong nước.","Chứng chỉ xác nhận năng lực ở lĩnh vực cụ thể, hỗ trợ tìm việc.","Chứng chỉ không bảo đảm lương cao."],
'nghe-nghe-16':["Cấu hình cáp quang là việc quản trị mạng.","Front-end: HTML và CSS dựng giao diện hiển thị trên trình duyệt.","Thiết kế mô hình dữ liệu là việc CSDL.","Bảo trì máy chủ là phần cứng."],
'nghe-nghe-17':["Lắp đặt Wi-Fi là việc kĩ thuật mạng.","Chọn màu, phông chữ là việc front-end/thiết kế.","Chỉnh ảnh là việc đồ hoạ.","Back-end xử lí nghiệp vụ, truy vấn CSDL và trả dữ liệu cho giao diện."],
'nghe-nghe-18':["Giám sát, định tuyến gói tin là phần mềm quản trị mạng.","Thiết kế đa phương tiện dùng phần mềm xử lí ảnh, âm thanh, video, hoạt hình.","Biên dịch mã nguồn là trình biên dịch.","Quản trị hệ quản trị CSDL là của quản trị CSDL."],
'nghe-nghe-19':["Soạn bài trình chiếu không phải kĩ năng mạng.","Dựng phim hoạt hình không liên quan.","Thiết kế mạng, cấu hình thiết bị mạng và bảo đảm an toàn.","Viết thuật toán sắp xếp không phải nhiệm vụ chính."],
'nghe-nghe-20':["Không phải mỗi người tự viết lại toàn bộ chương trình.","Pháp luật không cấm làm việc một mình.","Sản phẩm lớn do nhiều người phát triển và phối hợp nên cần làm việc nhóm.","Máy tính chạy được mã nguồn của một người."],
'nghe-nghe-21':["Duyệt hợp đồng tài chính không phải việc của tester.","Quyết định chức năng là của khách hàng và phân tích nghiệp vụ.","Tester thiết kế ca thử, tìm và báo cáo lỗi để nhóm sửa.","Tester không thay lập trình viên viết toàn bộ mã."],
'nghe-nghe-22':["Quản trị hệ thống làm việc với hệ điều hành, mạng chứ không chỉ phần mềm văn phòng.","Quản trị hệ thống vận hành, giám sát hệ thống sẵn có; phát triển phần mềm làm sản phẩm mới.","Quản trị hệ thống cần kiến thức mạng và hệ điều hành.","Cả hai nghề đều dùng máy tính."],
'more2-nghe-nghe-59':["Phát triển phần mềm gồm phân tích, thiết kế, lập trình, kiểm thử.","Sao lưu, phục hồi dữ liệu thuộc quản trị CSDL.","Đi dây, bảo trì mạng thuộc quản trị mạng.","Chỉnh ảnh, dựng video thuộc đa phương tiện."],
'more2-nghe-nghe-60':["Tìm quy luật trong số liệu và vẽ biểu đồ thuộc phân tích dữ liệu.","Thiết kế bao bì là đồ hoạ.","Quản trị mạng không làm việc này.","Sửa phần cứng không làm việc này."],
'more2-nghe-nghe-61':["AI không làm mọi công việc CNTT biến mất.","Nhu cầu nhân lực an toàn thông tin, dữ liệu, AI đang tăng.","Không chỉ còn sửa máy tính cũ.","CNTT cần học tập suốt đời."],
'more2-nghe-nghe-62':["Soạn văn bản không liên quan.","Giám sát hiệu năng giúp phát hiện truy vấn chậm, tối ưu hệ thống.","Thiết kế giao diện không phải việc của quản trị CSDL.","Lắp RAM không phải mục đích giám sát hiệu năng."],
'more2-nghe-nghe-63':["Bảng tính thống kê không phải kiến thức nền của an toàn thông tin.","Soạn thảo không đủ.","Chỉnh ảnh không đủ.","An toàn thông tin cần mạng, hệ điều hành, mật mã và các kiểu tấn công."],
'more2-nghe-nghe-64':["Đăng công khai dữ liệu khách hàng vi phạm riêng tư.","Dùng đúng mục đích và bảo vệ khỏi bị lộ là ưu tiên.","Sao chép ở mọi máy làm tăng nguy cơ lộ.","Bán hoặc chia sẻ cho đối tác khi chưa được phép là vi phạm."],
'more2-nghe-nghe-65':["Thiết kế trò chơi không làm việc này.","Quản trị hệ thống và mạng làm việc với hệ điều hành máy chủ, tài khoản, dịch vụ mạng.","Biên tập video không làm việc này.","Phân tích thị trường chứng khoán là tài chính."],
'more2-nghe-nghe-66':["Pháp luật không bắt buộc làm MC.","Máy tính chạy không cần người nói chuyện.","Cần trao đổi yêu cầu với khách hàng và đồng nghiệp nên giao tiếp quan trọng.","Mã nguồn không viết bằng lời nói."],
'more2-nghe-nghe-67':["Phóng viên không chăm sóc máy chủ.","Biên tập video không làm việc này.","Kĩ sư vận hành hệ thống máy chủ giám sát liên tục 24/7.","Thiết kế bao bì không liên quan."],
'more2-nghe-nghe-68':["Dùng ảnh bất kì có thể vi phạm bản quyền.","Xoá tên tác giả là thiếu trung thực.","Ghi rõ nguồn tài liệu, mã, ảnh thể hiện trung thực.","Nhận hết công sức của nhóm về mình là thiếu trung thực."],
'more2-nghe-nghe-69':["Chứng chỉ không thay kinh nghiệm.","Chứng chỉ chứng minh năng lực với nhà tuyển dụng.","Không bảo đảm được nhận vào mọi công ty.","Học tập vẫn cần tiếp tục."],
'more2-nghe-nghe-70':["Kiểm thử giúp phát hiện lỗi sớm để sửa trước khi bàn giao.","Không thay tài liệu hướng dẫn.","Kiểm thử không chứng minh chương trình hết lỗi.","Kiểm thử không nhằm giảm số dòng mã."],
'more2-nghe-nghe-71':["Lắp ráp phần cứng không phải nền tảng AI.","Chỉnh ảnh không phải nền tảng AI.","Kĩ sư AI cần toán – thống kê, lập trình, xử lí dữ liệu.","Gõ phím nhanh không quyết định."],
'more2-nghe-nghe-72':["Lập trình viên tạo chương trình, ứng dụng phần mềm.","Cáp mạng, thiết bị chuyển mạch thuộc kĩ thuật mạng.","Bản vẽ kiến trúc thuộc kiến trúc sư.","Bảng mạch chính thuộc kĩ sư phần cứng."],
}
